import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_ops, opp_ops = list(zip(*history))
    opp_c = opp_ops.count('C')
    opp_d = n - opp_c
    my_d = my_ops.count('D')
    opp_rate = (opp_c + 1.0) / (n + 2.0)

    last_me, last_opp = history[-1]

    recent = opp_ops[-6:]
    recent_c = recent.count('C')
    recent_d = len(recent) - recent_c

    streak_d = 0
    for x in reversed(opp_ops):
        if x == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for x in reversed(opp_ops):
        if x == 'C':
            streak_c += 1
        else:
            break

    remaining = 100 - n

    if opp_d == 0:
        if remaining <= 2:
            return 'D'
        if n >= 15 and n % 19 == 0 and my_d < 3:
            return 'D'
        return 'C'

    if my_d == 0 and opp_rate >= 0.85:
        return 'C'

    if opp_rate <= 0.25 or streak_d >= 3:
        return 'D'

    if streak_d == 1:
        if recent_d == 1 and opp_rate >= 0.6 and streak_c >= 2:
            return 'C'
        if opp_rate >= 0.65 and rng.random() < 0.35:
            return 'C'
        return 'D'

    if streak_d == 2:
        if opp_rate >= 0.7 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if my_d >= 2 and opp_rate >= 0.6 and recent_c >= 4:
        return 'C'

    if recent_d >= 3:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if remaining <= 3:
        if opp_rate >= 0.7 and streak_c >= 2:
            return 'D'
        if opp_rate <= 0.4:
            return 'D'

    if opp_rate >= 0.7:
        if n >= 30 and my_d == 0 and rng.random() < 0.06:
            return 'D'
        if last_me == 'D':
            return 'C'
        return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        if opp_rate >= 0.5 and rng.random() < 0.08:
            return 'D'
        return 'C'

    return 'D'
